// B15 Cash Flow Forecast — Aggregator
const setup = $('Edit Fields — Forecast Setup').item.json;
const todayIso = setup['todayIso'];
const in7 = setup['in7Iso'];
const in14 = setup['in14Iso'];
const in30 = setup['in30Iso'];

const trimKeys = (r) => { const o = {}; for (const [k, v] of Object.entries(r || {})) o[k.trim()] = v; return o; };
const safeRead = (name) => { try { return $(name).all().map(i => trimKeys(i.json)); } catch (e) { return []; } };
const toNum = (v) => { if (v == null) return 0; const n = parseFloat(String(v).replace(/[^0-9.-]/g, '')); return isNaN(n) ? 0 : n; };
const dateOnly = (v) => v ? String(v).slice(0, 10) : '';
const fmtR = (n) => 'R' + Math.round(n).toLocaleString('en-ZA');

const invoices = safeRead('Sheets — Read B4 Invoices');
const recurring = safeRead('Sheets — Read Recurring Log');

// --- Open invoices (not yet paid) ---
const openInvoices = invoices.filter(r => {
  const status = String(r['Status'] || '').toLowerCase();
  return status !== 'paid' && status !== 'recovered';
});

// --- Bucket by window ---
const inWindow = (dueDate, end) => {
  const d = dateOnly(dueDate);
  return d && d <= end;
};
const sumWindow = (end) => openInvoices.reduce((acc, r) => inWindow(r['Due Date'], end) ? acc + toNum(r['Invoice Amount']) : acc, 0);

const exp7 = sumWindow(in7);
const exp14 = sumWindow(in14);
const exp30 = sumWindow(in30);

// --- Recurring revenue (paid, with Billing Date in window) ---
const recurringInWindow = (end) => {
  const seen = new Set();
  let total = 0;
  for (const r of recurring) {
    const status = String(r['Status'] || '').toUpperCase();
    const billing = dateOnly(r['Billing Date']);
    const token = r['Token'] || r['Payment ID'];
    if (status !== 'COMPLETE' || !billing || billing < todayIso || billing > end) continue;
    if (seen.has(token)) continue;
    seen.add(token);
    total += toNum(r['Amount']);
  }
  return total;
};
const rec7 = recurringInWindow(in7);
const rec14 = recurringInWindow(in14);
const rec30 = recurringInWindow(in30);

// --- Risk flags ---
const overdue30 = openInvoices.filter(r => toNum(r['Days Overdue']) > 30);
const overdueAny = openInvoices.filter(r => toNum(r['Days Overdue']) > 0);
const totalOverdue = overdueAny.reduce((a, r) => a + toNum(r['Invoice Amount']), 0);

// --- Concentration (single debtor > 50% of 14-day expected) ---
const byDebtor = {};
for (const r of openInvoices) {
  if (!inWindow(r['Due Date'], in14)) continue;
  const k = r['Debtor Name'] || 'Unknown';
  byDebtor[k] = (byDebtor[k] || 0) + toNum(r['Invoice Amount']);
}
let concentration = null;
const total14 = exp14 || 1;
for (const [name, amt] of Object.entries(byDebtor)) {
  if (amt / total14 > 0.5) { concentration = { name, amt, pct: Math.round((amt / total14) * 100) }; break; }
}

// --- Recommended action: highest-R overdue invoice not at Stage 3 ---
let topAction = null;
const ranked = overdueAny
  .filter(r => String(r['Stage'] || '').toLowerCase() !== 'stage 3')
  .sort((a, b) => toNum(b['Invoice Amount']) - toNum(a['Invoice Amount']));
if (ranked.length > 0) {
  const top = ranked[0];
  const nextStage = String(top['Stage'] || 'Stage 1').toLowerCase().includes('1') ? 'Stage 2' : 'Stage 3';
  topAction = {
    text: 'Send ' + nextStage + ' chase to ' + (top['Debtor Name'] || 'unknown') + ' (' + (top['Invoice Number'] || '?') + ') — ' + fmtR(toNum(top['Invoice Amount'])) + ', ' + toNum(top['Days Overdue']) + ' days overdue.',
    invoiceNumber: top['Invoice Number'],
    debtor: top['Debtor Name'],
    amount: toNum(top['Invoice Amount']),
    daysOverdue: toNum(top['Days Overdue'])
  };
} else if (openInvoices.length === 0 && recurring.length === 0) {
  topAction = { text: 'No open invoices and no recurring revenue logged. Add invoices via /portal/recovery or onboard your first paying client.' };
} else {
  topAction = { text: 'All invoices on schedule. Focus on lead generation this week — try B7 referral asks for your top 3 customers.' };
}

const hasData = openInvoices.length > 0 || recurring.length > 0;

return {
  hasData,
  todayDisplay: setup['todayDisplay'],
  runAtSAST: setup['runAtSAST'],
  ownerEmail: setup['ownerEmail'],
  exp7, exp14, exp30,
  rec7, rec14, rec30,
  total7: exp7 + rec7, total14: exp14 + rec14, total30: exp30 + rec30,
  exp7Fmt: fmtR(exp7), exp14Fmt: fmtR(exp14), exp30Fmt: fmtR(exp30),
  rec7Fmt: fmtR(rec7), rec14Fmt: fmtR(rec14), rec30Fmt: fmtR(rec30),
  total7Fmt: fmtR(exp7 + rec7), total14Fmt: fmtR(exp14 + rec14), total30Fmt: fmtR(exp30 + rec30),
  openInvoiceCount: openInvoices.length,
  overdue30Count: overdue30.length,
  overdueAnyCount: overdueAny.length,
  totalOverdueFmt: fmtR(totalOverdue),
  concentration,
  topAction,
  topActionText: topAction.text,
  riskRows: overdueAny.slice(0, 8).map(r => ({
    debtor: r['Debtor Name'],
    invoice: r['Invoice Number'],
    amount: fmtR(toNum(r['Invoice Amount'])),
    days: toNum(r['Days Overdue']),
    stage: r['Stage'],
    severity: toNum(r['Days Overdue']) > 30 ? 'high' : (toNum(r['Days Overdue']) > 14 ? 'med' : 'low')
  }))
};

